MAX_BODY = 1_000_000

def acceptable_content_length(value):
    try:
        size = int(value)
        return 0 <= size <= MAX_BODY
    except (TypeError, ValueError):
        return False

print(acceptable_content_length('512'))

def is_json_content_type(value):
    return (value or '').split(';', 1)[0].strip().lower() == 'application/json'

print(is_json_content_type('application/json; charset=utf-8'))

def safe_headers(headers):
    hidden = {'authorization', 'cookie', 'set-cookie'}
    return {k: ('[REDACTED]' if k.lower() in hidden else v)
            for k, v in headers.items()}

print(safe_headers({'Authorization': 'Bearer demo', 'Accept': 'application/json'}))

