def validate_profile(data):
    if not isinstance(data, dict):
        return False
    allowed = {'display_name', 'bio'}
    if set(data) - allowed:
        return False
    name = data.get('display_name')
    bio = data.get('bio', '')
    return isinstance(name, str) and len(name) <= 40 and isinstance(bio, str) and len(bio) <= 300

print(validate_profile({'display_name': 'Lab User', 'bio': 'Practice account'}))

